<template><div class="app-container ps-page"><h2>模型供应商</h2><el-alert title="密钥通过已批准的秘密引用配置；页面不回显明文。Embedding 模型变化需要重建索引。" type="info" :closable="false" class="ps-section"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="ps-toolbar"><el-button v-hasPermi="['paismart:provider:edit']" type="primary" @click="create">新增供应商</el-button><el-button :loading="loading" @click="load">刷新配置</el-button><el-button v-hasPermi="['paismart:provider:edit']" @click="editScope('LLM')">配置对话模型</el-button><el-button v-hasPermi="['paismart:provider:edit']" @click="editScope('EMBEDDING')">配置向量模型</el-button><el-button v-hasPermi="['paismart:provider:edit']" @click="editScope('RERANK')">配置重排模型</el-button></div><el-table :data="providers" v-loading="loading"><el-table-column prop="scope" label="用途" width="130"/><el-table-column prop="provider" label="供应商" min-width="160"/><el-table-column prop="model" label="模型" min-width="210"/><el-table-column prop="address" label="地址" min-width="230"/><el-table-column prop="dimension" label="向量维度" width="110"/><el-table-column label="配置状态" width="150"><template #default="{row}">{{row.enabled?(row.configured?'已配置':'配置缺失'):'未启用'}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-hasPermi="['paismart:provider:edit']" link @click="edit(row)">编辑</el-button><el-button v-hasPermi="['paismart:provider:test']" link :loading="testing===String(row.id)" @click="test(row)">连接测试</el-button></template></el-table-column></el-table><el-alert v-if="testResult" :title="testResult" type="info" :closable="false"/><el-dialog v-model="open" :title="`供应商配置 · ${form.scope}`" width="680px"><el-form label-width="120px"><el-form-item label="模型用途"><el-select v-model="form.scope" :disabled="!!form.id"><el-option label="对话" value="LLM"/><el-option label="向量" value="EMBEDDING"/><el-option label="重排" value="RERANK"/></el-select></el-form-item><el-form-item label="供应商" required><el-select v-model="form.provider" allow-create filterable><el-option v-for="p in form.scope==='EMBEDDING'?['ALIYUN','ZHIPU']:['DEEPSEEK','QWEN','ZHIPU']" :key="p" :label="p" :value="p"/></el-select></el-form-item><el-form-item label="平台供应商编码"><el-input v-model="providerCode" placeholder="对应托管秘密元数据 providerCode，如 deepseek / dashscope"/><p class="ps-muted">该编码须与平台托管秘密的供应商和模型能力一致。</p></el-form-item><el-form-item label="模型" required><el-input v-model="form.model" maxlength="200"/></el-form-item><el-form-item label="API 地址" required><el-input v-model="form.address" placeholder="HTTPS 供应商地址" maxlength="1000"/></el-form-item><el-form-item v-if="form.scope==='EMBEDDING'" label="向量维度"><el-input-number v-model="form.dimension" :min="1" :max="16384" :precision="0"/></el-form-item><el-form-item label="秘密引用"><el-input v-model="form.secretRef" autocomplete="off" placeholder="留空保留既有引用；填写 ai.paismart.* 托管秘密引用" maxlength="200"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="激活此模型"><el-switch v-model="form.active" :disabled="!form.enabled"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onMounted,ref,shallowRef } from 'vue'
import { getProvider,listProviders,saveProvider,testProvider } from '@/api/paismart/operations'
import type { Provider } from '@/types/paismart'
import { errorText } from '../../composables/usePage'
import '../../common.css'
const providers=shallowRef<Provider[]>([]),loading=ref(false),saving=ref(false),open=ref(false),error=ref(''),formError=ref(''),testing=ref(''),testResult=ref(''),providerCode=ref(''),form=ref<Provider>({scope:'LLM',provider:'',model:'',address:'',enabled:false,rowVersion:0})
async function load(){loading.value=true;error.value='';try{providers.value=(await listProviders()).rows}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function edit(row:Provider){form.value={...row,config:{...row.config},secretRef:''};providerCode.value=String(row.config?.providerCode||'');formError.value='';open.value=true}
function create(){form.value={scope:'LLM',provider:'',model:'',address:'',enabled:false,active:false,rowVersion:0,config:{}};providerCode.value='';formError.value='';open.value=true}
async function editScope(scope:string){error.value='';try{edit((await getProvider(scope)).data)}catch(e){error.value=errorText(e)}}
async function save(){formError.value='';if(form.value.enabled&&(!form.value.model.trim()||!form.value.address.trim()||!form.value.provider)){formError.value='启用模型时请填写供应商、模型和地址';return}saving.value=true;try{await saveProvider({...form.value,config:{...form.value.config,...(providerCode.value.trim()?{providerCode:providerCode.value.trim()}:{})}});open.value=false;form.value.secretRef='';await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function test(row:Provider){testing.value=String(row.id);testResult.value='';try{const result=(await testProvider(row.scope,row.id)).data;testResult.value=`${row.provider} / ${row.model}：${result.state}，耗时 ${result.latencyMs} ms${result.reason?'，'+result.reason:''}`}catch(e){error.value=errorText(e)}finally{testing.value=''}}
onMounted(()=>void load())
</script>
